// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public {
        c = new X_WALLET(address(lg = new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // Rule: every successful Put must append a History entry recording the deposit.
        (address sender, , uint256 val, ) = lg.History(0);
        assertTrue(sender == actor && val == amount);
    }
}
